        sse_encode_i_32(13, serializer);
        sse_encode_list_String(condition, serializer);
        sse_encode_list_rust_ast(children, serializer);
      case RustAst_WhileLet(
        variant: final variant,
        variable: final variable,
        enum_: final enum_,
        children: final children,
      ):
        sse_encode_i_32(14, serializer);
        sse_encode_String(variant, serializer);
        sse_encode_String(variable, serializer);
        sse_encode_String(enum_, serializer);
        sse_encode_list_rust_ast(children, serializer);
      case RustAst_TraitDecl(pub: final pub, declarations: final declarations):
        sse_encode_i_32(15, serializer);
        sse_encode_bool(pub, serializer);
        sse_encode_list_rust_ast(declarations, serializer);
      case RustAst_Unknown():
        sse_encode_i_32(16, serializer);
    }
  }

  @protected
  void sse_encode_rust_token(RustToken self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_rust_token_kind(self.kind, serializer);
    sse_encode_String(self.text, serializer);
    sse_encode_record_usize_usize(self.span, serializer);
    sse_encode_usize(self.line, serializer);
    sse_encode_usize(self.col, serializer);
  }

  @protected
  void sse_encode_rust_token_kind(
    RustTokenKind self,
    SseSerializer serializer,
  ) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_i_32(self.index, serializer);
  }

  @protected
  void sse_encode_sql_token(SQLToken self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_sql_token_kind(self.kind, serializer);
    sse_encode_String(self.text, serializer);
    sse_encode_record_usize_usize(self.span, serializer);
    sse_encode_usize(self.line, serializer);
    sse_encode_usize(self.col, serializer);
  }

  @protected
  void sse_encode_sql_token_kind(SQLTokenKind self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_i_32(self.index, serializer);
  }

  @protected
  void sse_encode_u_8(int self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    serializer.buffer.putUint8(self);
  }

  @protected
  void sse_encode_unit(void self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
  }

  @protected
  void sse_encode_usize(BigInt self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    serializer.buffer.putBigUint64(self);
  }
}
